#nullable enable // autogenerated

using PVZEngine.Tools.Unity;

namespace MVZ2.Saves
{
    public static class OldSaveDataManager
    {
        public static void Import(SaveManager saveManager)
        {
            if (importer == null)
            {
                Log.LogWarning("OldSaveDataImporter is not set!");
                return;
            }
            importer.Import();
        }
        public static void SetSaveDataImporter(IOldSaveDataImporter importer)
        {
            OldSaveDataManager.importer = importer;
        }
        private static IOldSaveDataImporter? importer;
    }
    public interface IOldSaveDataImporter
    {
        void Import();
    }
}
